def compute(vars):
    subscription_returns_revenue = vars["v1"]
    total_revenue = vars["v2"]

    if total_revenue == 0:
        return None

    value = subscription_returns_revenue / total_revenue * 100
    return {
        "value": value,
        "trace": {
            "subscription_returns_revenue": subscription_returns_revenue,
            "total_revenue": total_revenue,
            "ratio": subscription_returns_revenue / total_revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
